package benign

import (
	"fmt"
	"strings"
	"time"
)

// headerIntro is the fixed description of how the index is built.
const headerIntro = `# corpus/benign/repos.lock
# Generated by scripts/benign-repos from the GitHub code search API
# (a read-only GITHUB_TOKEN). It searches for a root agent config:
# .claude/settings.json, .claude/settings.local.json, CLAUDE.md,
# .mcp.json, .cursor/, AGENTS.md, .vscode/tasks.json,
# .vscode/mcp.json, .github/copilot-instructions.md,
# .github/workflows/copilot-setup-steps.yml, .devcontainer/devcontainer.json,
# .devcontainer.json, .codex/config.toml, GEMINI.md, and .gemini/settings.json.
# A repository is kept when it has at least 50 stars and is not
# archived and not a fork. The list is stratified by harness and by
# repository size (small is under 1 MB, medium is under 10 MB, and
# large is the rest) and targets 1000 repositories.
`

const headerPolicy = `# A resumable crawl fills the list in.
# v0 doesn't ship until it reaches at least 1,000 repositories with a minimum per harness (#41).
`

const headerColumns = `# Columns, tab-separated: owner/repo, 40-character commit SHA of the
# default branch HEAD at generation time, SPDX license (NOASSERTION
# when the API reports none), harnesses (comma-separated), size band
# (small, medium, or large), date (YYYY-MM-DD).
`

// Header is the only comment prefix repos.lock may have for rows.
// The counts are computed from repos, so a hand-edited tally or an
// extra comment line does not match.
func Header(repos []Repo, when time.Time) string {
	var b strings.Builder
	b.WriteString(headerIntro)
	if len(repos) < 1000 {
		fmt.Fprintf(&b, "# This copy is partial: %d of 1000 repositories.\n", len(repos))
	} else {
		fmt.Fprintf(&b, "# This copy has %d repositories.\n", len(repos))
	}
	missing := missingHarnesses(repos)
	if len(missing) == 0 {
		b.WriteString("# Every harness has at least one row.\n")
	} else {
		fmt.Fprintf(&b, "# Harnesses with no rows yet: %s.\n", strings.Join(missing, ", "))
	}
	b.WriteString(headerPolicy)
	fmt.Fprintf(&b, "# Harness counts: %s.\n", harnessCountPhrase(repos))
	small, medium, large := bandCounts(repos)
	fmt.Fprintf(&b, "# Size bands: small %d, medium %d, large %d.\n", small, medium, large)
	b.WriteString(headerColumns)
	fmt.Fprintf(&b, "# Generated %s.\n", when.UTC().Format(time.DateOnly))
	b.WriteString("# This file changes only through a pull request.\n")
	return b.String()
}

func lockHeaderLines() int {
	return strings.Count(Header(nil, time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)), "\n")
}

func missingHarnesses(repos []Repo) []string {
	seen := map[string]bool{}
	for _, r := range repos {
		for _, h := range r.Harnesses {
			seen[h] = true
		}
	}
	var out []string
	for _, h := range Harnesses {
		if !seen[h] {
			out = append(out, h)
		}
	}
	return out
}

func harnessCountPhrase(repos []Repo) string {
	n := map[string]int{}
	for _, r := range repos {
		seen := map[string]bool{}
		for _, h := range r.Harnesses {
			if seen[h] || !knownHarness(h) {
				continue
			}
			seen[h] = true
			n[h]++
		}
	}
	parts := make([]string, len(Harnesses))
	for i, h := range Harnesses {
		parts[i] = fmt.Sprintf("%s %d", h, n[h])
	}
	return strings.Join(parts, ", ")
}

func bandCounts(repos []Repo) (small, medium, large int) {
	for _, r := range repos {
		switch bandOf(r) {
		case "small":
			small++
		case "medium":
			medium++
		case "large":
			large++
		default:
			large++
		}
	}
	return small, medium, large
}

func bandOf(r Repo) string {
	if r.Band != "" {
		return r.Band
	}
	return SizeBand(r.SizeKB)
}
